#!/usr/bin/env python3
"""B003: write the rights records for the initial corpus slate from the manifests on the NAS.

    python3 -I tools/b003_rights.py /Volumes/office-hub/openlogos/corpora

For every artifact in SLATE the script reads <storage>/<dir>/MANIFEST.sha256 (written by the
acquisition step: one '<sha256>  <path>' line per file, sorted), computes the manifest's own
SHA-256 (the record's artifact_sha256), stats the files for the byte total, looks up the licence
files' hashes in the manifest, copies the manifest to rights/<record>/manifest.sha256 when it is
under 200 KB, and writes rights/<record>.json (schema rights-record 1.1).

The slate itself, the flags and the coverage counts are data in this file so that a reviewer can
read the decision basis in one place; the counting rules name how each number was obtained.
No corpus byte is written into the repository. Nothing here is a legal determination: every
record is status "unknown" with a steward_proposal; the human source steward signs.
"""
import hashlib, json, sys
from pathlib import Path

REPO = Path(__file__).resolve().parents[1]
TODAY = '2026-10-28'
AGENT = 'b003 agent (Claude Fable 5.1) for the source steward'
MANIFEST_COPY_LIMIT = 200 * 1024

ALLOW = {k: 'allow' for k in ('local_read', 'redistribute', 'modify', 'public_index', 'model_prompt', 'model_train', 'translation_evaluate')}
def perms(**over):
    p = dict(ALLOW); p.update(over); return p
PD = perms()
CC_BY = perms()
CC_BY_SA = perms(model_train='unknown')
CC_BY_NC = perms(redistribute='deny', public_index='deny', model_train='deny', translation_evaluate='unknown')
CCEL = perms(redistribute='unknown', public_index='unknown', model_train='unknown', translation_evaluate='unknown')
CC_BY_FLAGGED = perms(redistribute='unknown', public_index='unknown', model_train='unknown')

def proposal(decision, rationale):
    return {'decision': decision, 'rationale': rationale, 'proposed_by': AGENT, 'proposed_on': TODAY}

