def read_manifest(p):
    rows = []
    for line in p.read_text(encoding='utf-8').splitlines():
        h, path = line.split('  ', 1)
        rows.append((path, h))
    return rows

def main(nas):
    nas = Path(nas)
    (REPO / 'rights').mkdir(exist_ok=True)
    summary = []
    for a in SLATE:
        d = nas / a['dir']
        mpath = d / 'MANIFEST.sha256'
        rows = read_manifest(mpath)
        mbytes = mpath.read_bytes()
        msha = hashlib.sha256(mbytes).hexdigest()
        hashes = dict(rows)
        total = sum((d / path).stat().st_size for path, _ in rows)
        if len(mbytes) <= MANIFEST_COPY_LIMIT:
            copy = REPO / 'rights' / a['record'] / 'manifest.sha256'
            copy.parent.mkdir(parents=True, exist_ok=True)
            copy.write_bytes(mbytes)
            manifest_path = f"rights/{a['record']}/manifest.sha256"
        else:
            manifest_path = None
        license_files = []
        for path, says in a['license_files']:
            if path not in hashes:
                raise SystemExit(f"{a['record']}: licence file {path} not in manifest")
            license_files.append({'path': path, 'sha256': hashes[path], 'says': says})
        rec = {
            'schema_version': '1.1',
            'id': f"rights:{a['record']}",
            'source_id': a['source_id'],
            'artifact_sha256': msha,
            'edition_id': a['edition_id'],
            'status': 'unknown',
            'license_identifier': a['license_identifier'],
            'evidence_url': a['evidence_url'],
            'license_artifact_sha256': hashes[a['license_of_record']],
            'jurisdictions': a['jurisdictions'],
            'attribution': a['attribution'],
            'permissions': a['permissions'],
            'reviewer': None,
            'reviewed_at': None,
            'acquisition': {
                'upstream_url': a['upstream_url'],
                'commit': a['commit'],
                'release': a['release'],
                'fetched_on': TODAY,
                'fetched_by': AGENT,
                'method': a['method'],
                'storage': f"/Volumes/office-hub/openlogos/corpora/{a['dir']}/ (NAS, SMB; MANIFEST.sha256 beside the data)",
                'paths': a['paths'],
                'file_count': len(rows),
                'bytes': total,
                'manifest_sha256': msha,
                'manifest_path': manifest_path,
                'fetch_seconds': a['fetch_seconds'],
            },
            'coverage': a['coverage'],
            'license_files': license_files,
            'flags': a['flags'],
            'upstream_dependencies': a['upstream_dependencies'],
            'steward_proposal': a['proposal'],
            'notes': a['notes'],
        }
        out = REPO / 'rights' / f"{a['record']}.json"
        out.write_text(json.dumps(rec, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
        summary.append((a['record'], len(rows), total, msha, a['proposal']['decision']))
    for s in summary:
        print('%-32s %5d files %12d bytes %s %s' % s)

if __name__ == '__main__':
    if len(sys.argv) != 2:
        raise SystemExit(__doc__)
    main(sys.argv[1])
